48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        owner.setHouseholdId(Households.householdId(owner));
98	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
99	        if (Households.memberCount(this.clinicService.findAllOwners(), owner) >= 3) {
100	            ownerDto.setMembershipLevel(4);
101	        }
102	        Integer possibleDuplicateOf = PossibleDuplicates.matchId(this.clinicService.findAllOwners(), owner);
103	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
104	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
105	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        Collection<Owner> owners = this.clinicService.findAllOwners();
114	        if (DailyRegistrations.countOn(owners, java.time.LocalDate.now()) >= 100) {
115	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
116	        }
117	        if (CityCodes.count(owners, owner) >= 50) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setHouseholdId(Households.householdId(owner));
121	        if (IdentityKeys.isDuplicate(owners, owner)) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && Households.isDuplicate(owners, owner)) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
